#include "stdlib/math/base/special/fast/gelu_tanh.h"
#include "stdlib/constants/float64/ninf.h"
#include "stdlib/constants/float64/nan.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/expit.h"

static const double SQRT_TWO_DIVIDED_BY_PI = 0.7978845608028654;

/**
* Evaluates the Gaussian Error Linear Unit (GELU) activation function using a tanh approximation.
*
* @param x    input value
* @return     function value
*
* @example
* double v = stdlib_base_fast_gelu_tanh( 0.0 );
* // returns 0.0
*/
double stdlib_base_fast_gelu_tanh( const double x ) {
	double z;

	if ( stdlib_base_is_nan( x ) ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	if ( x == STDLIB_CONSTANT_FLOAT64_NINF ) {
		return -0.0;
	}
	z = SQRT_TWO_DIVIDED_BY_PI * ( x + ( 0.044715 * x * x * x ) );
	return x * stdlib_base_expit( 2.0 * z );
}
